import sys
from typing import List, Tuple

def f(inputs: List[Tuple[int, int, List[Tuple[int, int, int]]]]): 
    results = []
    for ns, nl, tuples in inputs:
        if ns == 0 and nl == 0:
            break

        parent = list(range(ns + 1))
        rank = [0] * (ns + 1)

        def find(x: int):
            if parent[x]!= x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int):
            px, py = find(x), find(y)
            if px!= py:
                if rank[px] > rank[py]:
                    parent[py] = px
                elif rank[px] < rank[py]:
                    parent[px] = py
                else:
                    parent[py] = px
                    rank[px] += 1

        for s1, s2, d in sorted(tuples, key=lambda x: x[2]):
            union(s1, s2)

        components = set(find(x) for x in range(1, ns + 1))
        results.append(len(components))

    return results

def read_input():
    inputs = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line == '0 0':
            break
        ns, nl = map(int, line.split())
        tuples = []
        for _ in range(nl):
            tuples.append(tuple(map(int, input().split())))
        inputs.append((ns, nl, tuples))

    return inputs

def main():
    inputs = read_input()
    results = f(inputs)
    for result in results:
        print(result)

if __name__ == '__main__':
    main()
